package ru.edu.pr13; import java.util.concurrent.*; import java.util.concurrent.atomic.*; public class BatchResult { private final AtomicInteger success=new AtomicInteger(); private final ConcurrentMap<String,String> errors=new ConcurrentHashMap<>(); public void registerSuccess(){success.incrementAndGet();} public void registerError(String id,String msg){errors.put(id,msg);} public int successCount(){return success.get();} public ConcurrentMap<String,String> errors(){return errors;} }
